// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    Recorder rec;

    function setUp() public {
        c = new SimpleWallet();
        rec = new Recorder();
    }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, 1 ether);
        vm.deal(address(c), amount);
        vm.prank(address(this));
        c.sendMoney(address(rec), amount);
        assertTrue(rec.totalReceived() == amount, "callee must receive exactly the requested amount");
    }

    receive() external payable {}
}

contract Recorder {
    uint256 public totalReceived;
    receive() external payable { totalReceived += msg.value; }
}
